/** `<email>:o/r.git` / `https://host/o/r.git` → `https://host/o/r`, for linking commits. */
export function remoteWebUrl(remote: string | null): string | null {
  if (!remote) return null;
  const ssh = /^[\w.-]+@([\w.-]+):(.+?)(?:\.git)?$/.exec(remote);
